    out = [row[:] for row in grid]
    # Rows before the central blank band form one object, rows after it another.
    # Each object encodes a patterned strip and the final row is extended with 1s.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    occupied = [i for i, row in enumerate(grid) if any(v != bg for v in row)]
    if not occupied:
        return out
    # extend each object's last row through the remainder of the row
    groups = []
    group = [occupied[0]]
    for i in occupied[1:]:
        if i == group[-1] + 1:
            group.append(i)
        else:
            groups.append(group)
            group = [i]
    groups.append(group)
    for group in groups:
        r = group[-1]
        cols = [c for c, v in enumerate(grid[r]) if v != bg]
        if cols:
            for c in range(max(cols)+1, len(grid[r])):
                out[r][c] = 1
    return out
