 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Identify background as the most frequent color, then extend only isolated
    # 3-row motifs whose rightward continuation is still background.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = next(v for row in grid for v in row if v != bg)
    h, w = len(grid), len(grid[0])
    for r in range(h - 2):
        for c in range(w - 2):
            # Motif is a 3x3 pixel-art shape; extend its 3 rows rightward
            # when rows c..c+2 are the left portion of a repeated pattern.
            pass
    # From demonstrations, only the first multi-row motif at top is extended:
    # fill to the right on its rows containing the repeated emblem, not the
    # unrelated single-row elements. Detect 3-row block by identical motif columns.
    rows = [i for i, row in enumerate(grid) if any(v != bg for v in row)]
    if rows:
        # Contiguous colored row groups; extend rows whose foreground occupies
        # the leftmost 3-column motif and whose cells after the motif are blank.
        for start in rows:
            for c in range(w):
                if grid[start][c] == bg:
                    continue
            # specific rule: rows with foreground in initial 3x3 motif and no
            # foreground beyond column 5 are the motif continuation rows.
        # motifs occur as 3-row blocks; in each block, extend rows of the
        # leftmost emblem (first 3 columns) when it is a 3x3 pattern.
        for r in range(h - 2):
            if all(any(grid[rr][c] != bg for c in range(3)) for rr in range(r, r+3)):
                # require 3x3 emblem has at least one background in each row
                if all(any(grid[rr][c] == bg for c in range(3)) for rr in range(r, r+3)):
                    for rr in range(r, r+3):
                        # Extend from right edge of encoded emblem content
                        end = max((c for c,v in enumerate(grid[rr]) if v != bg), default=-1)
                        for c in range(end+1, w): out[rr][c] = 1
                    break
    return out
