    out=[row[:] for row in grid]
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Horizontal strips encoding a pattern are terminated by a long blank tail;
    # color that tail 1 on the first row of each pattern instance.
    occupied=[r for r,row in enumerate(grid) if any(v!=bg for v in row)]
